import {SYSTEMS,SHIPS,UPGRADES,getStats,jumpDistance,jumpCost,findRoute,systemName,guildProgress,operationDetails,FACTIONS,GUILDS,MODULES,moduleSlots,systemLayoutMeta} from './frontier.mjs';
import {STATION_ROBOT,ensureRobotState} from './station-robot.mjs';
import {hullPreviewSvg} from './hull-defs.mjs';
const fmt=n=>Math.round(n).toLocaleString(),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),row=(a,b)=>`<div class="data-row"><span>${a}</span>${b}</div>`;
function robotFaceSvg(expression='neutral'){
 return `<svg class="robot-portrait" viewBox="0 0 148 104" aria-hidden="true">
  <rect x="8" y="10" width="132" height="84" rx="10" fill="#0c1822" stroke="#6db6ad" stroke-width="2.2"/>
  <rect x="14" y="16" width="120" height="72" rx="6" fill="#08141c" stroke="#29404c" stroke-width="1.2"/>
  <g class="robot-face robot-face--${esc(expression)}">
   <rect class="robot-screen" x="22" y="24" width="104" height="56" rx="5" fill="#102834"/>
   <circle cx="30" cy="32" r="2.2" fill="#90efdc" opacity=".55"/>
   <g class="robot-eyes">
    <rect class="robot-eye robot-eye-l" x="42" y="38" width="16" height="16" rx="3" fill="#90efdc"/>
    <rect class="robot-eye robot-eye-r" x="90" y="38" width="16" height="16" rx="3" fill="#90efdc"/>
   </g>
   <rect class="robot-mouth" x="58" y="66" width="32" height="5" rx="2.5" fill="#6db6ad"/>
   <path class="robot-brow robot-brow-l" d="M40 32h20" stroke="#6db6ad" stroke-width="2" stroke-linecap="round"/>
   <path class="robot-brow robot-brow-r" d="M88 32h20" stroke="#6db6ad" stroke-width="2" stroke-linecap="round"/>
  </g>
  <rect x="66" y="90" width="16" height="4" rx="1" fill="#3a5560"/>
 </svg>`;
}
function robotActions(docked){
 return `<div class="section-actions robot-actions"><button class="primary" data-action="robot-talk" ${!docked?'disabled':''}>Talk</button><button data-action="robot-tip" ${!docked?'disabled':''}>Ask for a tip</button></div>`;
}
/** Compact face + dialogue strip shown on the Market tab. */
export function robotStrip(game){
 const state=ensureRobotState(game),name=STATION_ROBOT.nameFor(game.sys);
 const quote=state.lastText||'Dock services online. Tap Talk — or ask for a tip you will probably ignore.';
 return `<aside class="robot-strip" aria-label="${esc(name)} station concierge">
  <div class="robot-strip-face">${robotFaceSvg(state.expression||'neutral')}</div>
  <div class="robot-strip-copy">
   <div class="robot-strip-head"><div class="eyebrow">${esc(STATION_ROBOT.roleLabel)}</div><strong>${esc(name)}</strong></div>
   <blockquote class="robot-quote"><p>${esc(quote)}</p></blockquote>
   ${robotActions(!!game.s.docked)}
  </div>
 </aside>`;
}
function shipPreview(b){return hullPreviewSvg(b);}
function shipMatchesFilter(b,filter){
 if(filter==='all')return true;
 if(filter==='explorer')return b.class==='explorer'||b.class==='scout';
 return b.class===filter;
}
export function moduleView(game){const s=game.s,active=s.loadouts[s.ship],st=getStats(s),card=m=>{const d=MODULES[m.kind],loc=game.moduleLocation(m.uid),installed=loc===s.ship;return `<article class="module-card ${installed?'installed':''}"><div><span class="tag ${d.guild?'safe':''}">${d.guild?'Guild reward':'Grade '+m.grade} · ${d.category}</span><h3>${d.name}${d.standard?' '+['','I','II','III'][m.grade]:''}</h3><p>${d.desc}</p><small>${loc?'Fitted to '+SHIPS.find(b=>b.id===loc).name:'In module storage'}</small></div><button data-action="${installed?'unequip':'equip'}" data-id="${m.uid}" ${!s.docked?'disabled':''}>${installed?'Remove':loc?'Move here':'Install'}</button></article>`;};return `<div class="section-heading"><h3>${st.name} · ${active.length} / ${moduleSlots(s.ship)} slots</h3><span class="tag safe">${st.range} ly · ${st.cargo} t</span></div><p class="intro">One module per category. Weapon hardpoints choose Pulse, Beam, or Seeker fire modes. Dock to remove modules into storage or transfer them from another owned ship. Ship purchases stay in your hangar.</p><div class="module-list">${s.modules.filter(m=>active.includes(m.uid)).map(card).join('')||'<p class="detail-text">No optional modules installed. Your ship’s basic systems are ready to fly.</p>'}</div><h3 class="section-title">Storage & other ships</h3><div class="module-list">${s.modules.filter(m=>!active.includes(m.uid)).map(card).join('')||'<p class="detail-text">Guild rewards arrive here. Existing upgrades become removable modules.</p>'}</div><h3 class="section-title">Standard modules</h3><div class="upgrade-list">${Object.values(MODULES).filter(u=>u.standard).map(u=>{const m=s.modules.find(m=>m.kind===u.id&&active.includes(m.uid)),grade=m?.grade||0,cost=u.price*(grade+1);return `<div class="upgrade-row"><div><h3>${u.name}</h3><p>${u.desc}</p><div class="pips">${[0,1,2].map(i=>`<i class="${i<grade?'on':''}"></i>`).join('')}</div></div><button data-action="upgrade" data-id="${u.id}" ${!s.docked||grade>=3||s.credits<cost||(!m&&active.length>=moduleSlots(s.ship))?'disabled':''}>${grade>=3?'Grade III':(grade?'Upgrade':'Buy')+' · '+fmt(cost)+' cr'}</button></div>`;}).join('')}</div>`;}
export function fleetView(game,filter='all'){const s=game.s,filters=[['all','All'],['explorer','Explorer'],['trader','Trader'],['miner','Miner'],['combat','Combat'],['courier','Courier']],list=SHIPS.filter(b=>shipMatchesFilter(b,filter));return `<p class="intro">Switch between owned ships for free. Each hull has its own silhouette, modules, hull condition, and fuel. Cargo travels with you. ${SHIPS.length} hulls in the yard.</p><div class="ship-filters" role="tablist" aria-label="Filter ships by role">${filters.map(([id,label])=>`<button type="button" role="tab" data-action="ship-filter" data-id="${id}" class="${filter===id?'active':''}" aria-selected="${filter===id?'true':'false'}">${label}</button>`).join('')}</div><div class="ship-grid">${list.map(b=>{const current=b.id===s.ship,owned=s.fleet.includes(b.id),st=getStats({...s,ship:b.id}),cost=owned?0:b.price;return `<article class="card ship-card ${current?'selected':''}" style="--ship:${b.color}"><div class="eyebrow">${b.role}</div><h3>${b.name}</h3>${shipPreview(b)}<p>${b.desc}</p>${row('Cargo',st.cargo+' t')}${row('Jump range',st.range+' ly')}${row('Module slots',moduleSlots(b.id))}${row('Hull / shield',st.hull+' / '+st.shield)}<button data-action="buy-ship" data-id="${b.id}" class="primary" ${!s.docked||current||s.credits<cost?'disabled':''}>${current?'Current ship':owned?'Switch ship':'Buy · '+fmt(cost)+' cr'}</button></article>`;}).join('')||'<p class="detail-text">No ships in this role.</p>'}</div>`;}
export function guildView(game){const s=game.s;return `<p class="intro">Join any or all four guilds for free. Each offers three commissions with unique transferable modules. Accept and claim at any station’s guild desk.</p><div class="guild-grid">${GUILDS.map(g=>{const state=s.guilds[g.id],p=guildProgress(s,g.id),q=p.quest;return `<article class="card guild-card" style="--guild:${g.color}"><span class="tag">${state.joined?'Member · '+state.stage+'/3':'Open membership'}</span><h3>${g.name}</h3><p>${g.desc}</p>${p.done?'<div class="reward-box">Guild mastery complete. All three modules are yours.</div>':`<div class="commission"><div class="eyebrow">COMMISSION ${state.stage+1} / 3</div><h4>${q.name}</h4><p>${q.desc}</p><div class="reward-box"><strong>${MODULES[q.reward].name}</strong><span>${MODULES[q.reward].desc}</span><small>Plus ${fmt(q.credits)} cr</small></div>${state.active?`<div class="quest-progress">${fmt(p.current)} / ${fmt(p.total)}<div class="meter"><i style="width:${p.current/p.total*100}%"></i></div></div>`:''}</div>`}${p.done?'':!state.joined?`<button data-action="join-guild" data-id="${g.id}" ${!s.docked?'disabled':''}>Join guild</button>`:!state.active?`<button data-action="accept-guild" data-id="${g.id}" ${!s.docked?'disabled':''}>Accept commission</button>`:`<button data-action="claim-guild" data-id="${g.id}" class="${p.ready?'primary':'quiet'}" ${!s.docked||!p.ready?'disabled':''}>${p.ready?'Claim reward':'In progress'}</button>`}${!s.docked?'<p class="detail-text">Visit a guild desk to accept or claim.</p>':''}</article>`;}).join('')}</div>`;}
export function factionView(game){const s=game.s;return `<h3 class="section-title">Active operations · ${s.operations.length} / 3</h3><div class="cards">${operationCards(game)}</div><p class="intro">Relief and combat operations build standing. Friendly factions offer better local prices; hostile factions send patrols after you. Pledged patrols assist nearby fights.</p><div class="faction-grid">${FACTIONS.map(f=>{const rep=s.reputation[f.id],pledged=s.allegiance===f.id;return `<article class="card faction-card" style="--guild:${f.color}"><span class="tag ${rep>=20?'safe':rep<=-20?'danger':''}">${rep>=20?'Friendly':rep<=-20?'Hostile':'Neutral'} · ${rep>0?'+':''}${rep}</span><h3>${f.name}</h3><p>${f.desc}</p><div class="rep-meter"><i style="left:50%;width:${Math.abs(rep)/2}%;transform:${rep<0?'translateX(-100%)':'none'};background:${rep<0?'#ed8b87':f.color}"></i></div><button data-action="pledge" data-id="${pledged?'independent':f.id}" class="${pledged?'primary':'quiet'}">${pledged?'Pledged · leave':'Support faction'}</button><div class="faction-jobs">${[['relief','Relief operation'],['combat','Combat operation']].map(([type,label])=>`<button data-action="operation-${type}" data-id="${f.id}" ${!s.docked||s.operations.length>=3||s.operations.some(o=>o.faction===f.id&&o.type===type)?'disabled':''}>${label}</button>`).join('')}</div></article>`;}).join('')}</div>`;}
export function mapView(game,selected,query='',filter='all'){const s=game.s,st=getStats(s),sys=SYSTEMS[selected],known=!sys.uncharted||s.visited.includes(sys.id),current=selected===s.system,path=findRoute(s.system,selected,st.range),route=s.route,next=route?.path?.[0],fuel=path?.reduce((sum,id,i)=>sum+jumpCost(i?path[i-1]:s.system,id,s),0)||0,matches=SYSTEMS.filter(x=>(filter==='all'||filter==='charted'&&!x.uncharted||filter==='uncharted'&&x.uncharted||filter==='visited'&&s.visited.includes(x.id))&&(!query||systemName(x,s).toLowerCase().includes(query.toLowerCase())||(x.catalog||'').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>jumpDistance(s.system,a.id)-jumpDistance(s.system,b.id)),can=!s.docked&&!game.surface&&!game.jump&&next!=null&&s.fuel>=jumpCost(s.system,next,s)&&jumpDistance(s.system,next)<=st.range;
 const meta=systemLayoutMeta(sys),starTag=meta.starCount===3?'Trinary':meta.starCount===2?'Binary':'Single star';
 return `<div class="chart-toolbar"><label class="chart-search"><span class="sr-only">Find a system</span><input id="map-search" type="search" placeholder="Find a system or UR code" value="${esc(query)}" autocomplete="off"></label><select id="map-filter" aria-label="Filter systems">${[['all','All regions'],['charted','Charted space'],['uncharted','Uncharted Reach'],['visited','Visited']].map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="map-layout"><div class="map-surface"><canvas class="galaxy-map" id="galaxy-map" aria-label="Drag to pan, pinch to zoom, tap a star"></canvas><div class="chart-controls"><button data-action="map-zoom" data-id="in" aria-label="Zoom in">+</button><button data-action="map-zoom" data-id="out" aria-label="Zoom out">−</button><button data-action="map-home">Locate me</button><button data-action="map-overview">Overview</button></div><div class="map-legend"><span class="accent">● Visited</span><span>○ Uncharted</span><span>Gold: route</span></div></div><div class="map-side"><span class="tag ${known&&sys.danger>1?'risk':'safe'}">${sys.uncharted?(known?'Discovered':'Uncharted Reach'):['Secure','Patrolled','Contested','Lawless'][sys.danger]}</span><h2>${systemName(sys,s)}</h2>${row('Economy',known?sys.eco:'Unknown')}${row('Stars',known?starTag:'Unconfirmed')}${row('Worlds',known?String(meta.planetCount):'Unconfirmed')}${row('Station',known?(sys.hasStation?(sys.prison?'Prison · ':'')+sys.station+(meta.stationCount>1?' · '+meta.stationCount+' docks':''):'None · scoop at star'):'Unconfirmed')}${row('Faction',known?(FACTIONS.find(f=>f.id===sys.faction)?.name||'Unclaimed'):'Unknown')}${row('Distance',current?'You are here':jumpDistance(s.system,selected).toFixed(1)+' ly')}${row('Route',path?path.length+' jumps':'No route')}${row('Total fuel',fuel+' units')}<button data-action="plot-route" data-id="${selected}" ${current||!path?'disabled':''}>${current?'You are here':path?.length===1?'Plot direct route':'Plot route'}</button>${fuel>s.fuel?'<div class="range-message">Refuel along this route. Stars can replenish your tank.</div>':''}</div></div>${route?`<div class="route-bar"><div><strong>${route.path.length?'Route to '+systemName(SYSTEMS[route.destination],s):'Route complete'}</strong><span>${next!=null?'Next: '+systemName(SYSTEMS[next],s)+' · '+jumpCost(s.system,next,s)+' fuel':'Destination reached'}</span></div><button class="primary" data-action="jump-next" ${!can?'disabled':''}>${s.docked?'Launch to jump':game.surface?'Return to orbit':next==null?'Arrived':'Jump next'}</button><button class="quiet" data-action="clear-route" aria-label="Clear route">×</button></div>`:''}<div class="chart-results">${matches.slice(0,16).map(x=>`<button data-action="select-system" data-id="${x.id}" class="${x.id===selected?'active':''}"><span>${systemName(x,s)}</span><small>${jumpDistance(s.system,x.id).toFixed(1)} ly ${s.visited.includes(x.id)?'· visited':''}</small></button>`).join('')||'<p class="detail-text">No matching systems.</p>'}</div><p class="intro chart-note">${matches.length} matching systems · 64 core worlds, 128 uncharted systems surrounding them. Drag to pan; pinch to zoom. Contracts plot routes directly.</p>`;
}

export function operationCards(game){const s=game.s;return s.operations.map(o=>{const d=operationDetails(s,o);return `<article class="card"><div class="eyebrow">${FACTIONS.find(f=>f.id===o.faction).name}</div><h3>${d.title}</h3><p>${d.desc}</p><p class="accent">Next: ${d.next}</p><div class="quest-progress">${d.current} / ${d.total} · ${fmt(d.reward)} cr</div><div class="card-bottom"><button data-action="route-operation" data-id="${o.uid}">${d.navLabel}</button><button data-action="claim-operation" data-id="${o.uid}" class="primary" ${!s.docked||!d.ready?'disabled':''}>Report success</button></div></article>`;}).join('')||'<p class="detail-text">Visit a station to accept operations. Pledging is optional.</p>';}
